import React from "react";
import ReactDOM from "react-dom";
import { HashRouter } from "react-router-dom";

import App from "./App";

ReactDOM.render(
  // Load HashRouter as soon as possible so that we can use reactrouter
  // hooks in App. HashRouter is used so the app works under any sub-path
  // on GitHub Pages without server-side rewrites.
  <HashRouter>
    <App />
  </HashRouter>,
  document.querySelector(".container")
);
